const crypto=require('crypto');
const h=$json.headers||{};
const value=String(h.authorization||h.Authorization||'');
const token=value.startsWith('Bearer ')?value.slice(7).trim():'';
return [{json:{token_hash:token?crypto.createHash('sha256').update(token).digest('hex'):'missing'}}];

const rows=$input.all().map(item=>item.json);
const num=v=>Number(String(v??'').replace(/[₹,%\s]/g,'').replace(/,/g,''))||0;
const summaries=[];const campaigns=[];const weekly=[];let updatedAt='';
for(const row of rows){
 const type=String(row.record_type||row.type||'').trim().toLowerCase();
 const period=String(row.period||row.month||'').trim();
 updatedAt=String(row.updated_at||updatedAt).trim();
 if(type==='summary')summaries.push({period,content:{postersGenerated:num(row.posters_generated),postersPosted:num(row.posters_posted),blogs:num(row.blogs),newsletters:num(row.newsletters),videos:num(row.videos),scheduled:num(row.scheduled)},totals:{impressions:num(row.impressions),clicks:num(row.clicks),leads:num(row.leads),spend:num(row.spend),engagement:num(row.engagement)}});
 if(type==='campaign')campaigns.push({period,platform:String(row.platform||'').trim(),name:String(row.campaign_name||row.name||'').trim(),status:String(row.status||'').trim(),spend:num(row.campaign_spend||row.spend),impressions:num(row.campaign_impressions||row.impressions),clicks:num(row.campaign_clicks||row.clicks),leads:num(row.campaign_leads||row.leads)});
 if(type==='weekly')weekly.push({period,label:String(row.week_label||row.label||'').trim(),google:num(row.google_leads),meta:num(row.meta_leads),organic:num(row.organic_leads)});
}
if(!summaries.length)throw new Error('No marketing summary rows found');
return [{json:{success:true,updatedAt,summaries,campaigns,weekly}}];
